+/*
+// Ensure that exception handler preserves the verification state before the putfield
+value class HasStrictField {
+   Foo sf;
+   HasStrictField(Foo something) {
+      try {
+        this.sf = something;
+      }
+      catch (Throwable ex) {
+        //do nothing
+      }
+   }
+}
+*/
+
+final class HasStrictField version 72:65535
+{
+  final strict Field sf:"Ljava/lang/Integer;";
+
+  Method       "<init>":"(Ljava/lang/Integer;)V"
+    stack 2  locals 3
+  {
+         aload_0;
+         aload_1;
+         try               T0;
+         putfield          Field sf:"Ljava/lang/Integer;";
+         endtry            T0;
+         goto              L12;
+         catch             T0 java/lang/Throwable;
+         stack_frame_type  early_larval;
+           unset_fields;   // Should be sf:"Ljava/lang/Integer;"
+           frame_type      stack1;
+             stack_map     class java/lang/Throwable;
+         pop;
+  L12:   stack_frame_type  same;
+         aload_0;
+         invokespecial     Method java/lang/Object."<init>":"()V";
+         return;
+  }
+
+  SourceFile               "HasStrictField.java";
+
+  LoadableDescriptors      "Ljava/lang/Integer;";
+} // end Class HasStrictField compiled from "HasStrictField.java"

